function mergeCreases(){for(let i=0;i<creases.length;i++){let a=creases[i],dx=a.b.x-a.a.x,dy=a.b.y-a.a.y,L=Math.hypot(dx,dy);if(L<EPS)continue;for(let j=i+1;j<creases.length;j++){let b=creases[j];if(a.piece!==b.piece)continue;let signed=p=>((p.x-a.a.x)*dy-(p.y-a.a.y)*dx)/L;if(Math.abs(signed(b.a))>.01||Math.abs(signed(b.b))>.01)continue;let t=p=>((p.x-a.a.x)*dx+(p.y-a.a.y)*dy)/(L*L),lo=Math.min(t(b.a),t(b.b)),hi=Math.max(t(b.a),t(b.b));if(lo>1.0001||hi<-.0001)continue;let origin={...a.a};a.a={x:origin.x+Math.min(0,lo)*dx,y:origin.y+Math.min(0,lo)*dy};a.b={x:origin.x+Math.max(1,hi)*dx,y:origin.y+Math.max(1,hi)*dy};creases.splice(j,1);i=-1;break}}}
